const localeTags: Record<SupportedLocale, string> = {
  fr: "fr-FR", en: "en-US", de: "de-DE", es: "es-ES", it: "it-IT",
};

const visualLabels: Record<SupportedLocale, Messages> = {
  en: {
    Rest: "Rest",
    Plan: "Plan",
    PR: "PR",
    "Last time: {kg} × {reps}": "Last time: {kg} × {reps}",
  },
  fr: {
    Rest: "Repos",
    Plan: "Plan",
    PR: "PR",
    "Last time: {kg} × {reps}": "La dernière fois : {kg} × {reps}",
  },
  de: {
    Rest: "Pause",
    Plan: "Plan",
    PR: "PR",
    "Last time: {kg} × {reps}": "Letztes Mal: {kg} × {reps}",
  },
  es: {
    Rest: "Descanso",
    Plan: "Plan",
    PR: "PR",
    "Last time: {kg} × {reps}": "La última vez: {kg} × {reps}",
  },
  it: {
    Rest: "Recupero",
    Plan: "Piano",
    PR: "PR",
    "Last time: {kg} × {reps}": "L'ultima volta: {kg} × {reps}",
  },
};

const supportedLocales = new Set<SupportedLocale>(["fr", "en", "de", "es", "it"]);
const deviceLocale = getLocales()[0]?.languageCode;
const initialLocale: SupportedLocale = supportedLocales.has(deviceLocale as SupportedLocale)
  ? (deviceLocale as SupportedLocale)
  : "fr";

const i18n = createInstance();

void i18n.use(initReactI18next).init({
  resources: Object.fromEntries(
    Object.entries(messages).map(([locale, translation]) => [
      locale,
      { translation: { ...translation, ...sharedMessages[locale as SupportedLocale], ...communityMessages[locale as SupportedLocale], ...analyticsMessages[locale as SupportedLocale], ...personalSpaceMessages[locale as SupportedLocale], ...supportMessages[locale as SupportedLocale], ...waveAMessages[locale as SupportedLocale], ...activityDayMessages[locale as SupportedLocale], ...recorderMessages[locale as SupportedLocale], ...accountingMessages[locale as SupportedLocale], ...gymMessages[locale as SupportedLocale], ...trendsMessages[locale as SupportedLocale], ...visualLabels[locale as SupportedLocale], ...coachChatMessages[locale as SupportedLocale], ...referralMessages[locale as SupportedLocale], ...weeklyReviewMessages[locale as SupportedLocale], ...storeBillingMessages[locale as SupportedLocale] } },
    ]),
  ),
  lng: initialLocale,
  fallbackLng: "en",
  supportedLngs: [...supportedLocales],
  interpolation: {
    escapeValue: false,
    prefix: "{",
    suffix: "}",
  },
  react: { useSuspense: false },
});

type I18nContextValue = {
  locale: SupportedLocale;
  localeTag: string;
  t: (source: string, values?: Record<string, string | number>) => string;
  formatDate: (value: Date | string | number, options?: Intl.DateTimeFormatOptions) => string;
  formatNumber: (value: number, options?: Intl.NumberFormatOptions) => string;
};

const I18nContext = createContext<I18nContextValue | null>(null);

export function I18nProvider({ children }: { children: ReactNode }) {
  const { user } = useAuth();
  const locale = user?.preferred_locale ?? initialLocale;
  const localeTag = localeTags[locale];
  const { t: translate } = useTranslation();
  useEffect(() => {
    void i18n.changeLanguage(locale);
  }, [locale]);
  const t = useCallback(
    (source: string, values?: Record<string, string | number>) =>
      translate(source, { ...values, defaultValue: source }),
    [translate],
  );
  const formatDate = useCallback(
    (value: Date | string | number, options?: Intl.DateTimeFormatOptions) =>
      new Intl.DateTimeFormat(localeTag, options).format(new Date(value)),
    [localeTag],
  );
  const formatNumber = useCallback(
    (value: number, options?: Intl.NumberFormatOptions) =>
      new Intl.NumberFormat(localeTag, options).format(value),
    [localeTag],
  );
  return (
    <I18nContext.Provider
      value={{
        locale,
        localeTag,
        t,
        formatDate,
        formatNumber,
      }}
    >
      {children}
    </I18nContext.Provider>
  );
}

export function useI18n() {
  const context = useContext(I18nContext);
  if (!context) throw new Error("useI18n must be used within I18nProvider");
  return context;
}